# Generated by build.py from recipe.yml for recipe smtp-send-a-batch-of-mails-from-files. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p outbox
cat > outbox/order-101.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 101 shipped

Order 101 is on its way.
EOF
cat > outbox/order-102.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 102 shipped

Order 102 is on its way.
EOF
cat > outbox/order-103.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 103 shipped

Order 103 is on its way.
EOF
surl --mail-domain example.com --mailbox shop@example.com:shoppass --mailbox ann@example.com:annpass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "outbox/order-[101-103].eml" -w "%{response_code} %{num_connects}\n" smtp://127.0.0.1:8080/example.com --next -u ann@example.com:annpass -X "STATUS INBOX (MESSAGES)" imap://127.0.0.1:8081/
kill $(jobs -p)
